const map = {
a: 1,
b: 2,
c: 3,
} as const;
type Map = typeof map;
type Params = { [K in keyof Map]: { k: K; value: Map[K] } }[keyof Map];
function fn(params: Params) {
const {k, value} = params;
if (k === 'a') {
console.log(value); // value: 1
} else if (k === 'b') {
console.log(value); // value: 2
} else if (k === 'c') {
console.log(value); // value: 3
}
}
fn({k: 'a', value: 1});
fn({k: 'b', value: 2});
fn({k: 'c', value: 3});
